const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Mount Fuji location
  const mountFuji = ee.Geometry.Point([138.73, 35.36]);
  const roi = mountFuji.buffer(5000); // 5km buffer

  // Define time periods
  const dec2019Start = '2019-12-01';
  const dec2019End = '2019-12-31';
  const dec2020Start = '2020-12-01';
  const dec2020End = '2020-12-31';

  // Function to mask clouds using QA60
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    return image.updateMask(qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0)));
  }

  // Function to calculate NDSI
  function addNDSI(image) {
    const ndsi = image.normalizedDifference(['B3', 'B11']).rename('NDSI');
    return image.addBands(ndsi);
  }

  // Load Sentinel-2 for December 2019
  const s2_2019 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(roi)
    .filterDate(dec2019Start, dec2019End)
    .map(maskClouds)
    .map(addNDSI);

  const size2019 = s2_2019.size().getInfo();
  console.log('December 2019 Images: ' + size2019);

  if (size2019 === 0) {
    console.log('No images for December 2019.');
    console.log('C1');
    return;
  }

  // Load Sentinel-2 for December 2020
  const s2_2020 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(roi)
    .filterDate(dec2020Start, dec2020End)
    .map(maskClouds)
    .map(addNDSI);

  const size2020 = s2_2020.size().getInfo();
  console.log('December 2020 Images: ' + size2020);

  if (size2020 === 0) {
    console.log('No images for December 2020.');
    console.log('C1');
    return;
  }

  // Calculate median composite for each period
  const comp2019 = s2_2019.median();
  const comp2020 = s2_2020.median();

  // Check pixel counts
  const pixelCount2019 = comp2019.select('NDSI').reduceRegion(
    {reducer: ee.Reducer.count(), geometry: roi, scale: 1000, maxPixels: 1e9}
  ).getInfo().NDSI;

  const pixelCount2020 = comp2020.select('NDSI').reduceRegion(
    {reducer: ee.Reducer.count(), geometry: roi, scale: 1000, maxPixels: 1e9}
  ).getInfo().NDSI;

  console.log('Valid pixels 2019: ' + pixelCount2019 + ', 2020: ' + pixelCount2020);

  if (pixelCount2019 === 0 || pixelCount2020 === 0) {
    console.log('No valid pixels after masking.');
    console.log('C2');
    return;
  }

  // Calculate mean NDSI for both periods
  const ndsi2019 = comp2019.select('NDSI').reduceRegion(
    {reducer: ee.Reducer.mean(), geometry: roi, scale: 1000, maxPixels: 1e9}
  ).getInfo().NDSI;

  const ndsi2020 = comp2020.select('NDSI').reduceRegion(
    {reducer: ee.Reducer.mean(), geometry: roi, scale: 1000, maxPixels: 1e9}
  ).getInfo().NDSI;

  console.log('Mean NDSI Dec 2019: ' + (ndsi2019 !== null ? ndsi2019.toFixed(4) : 'null'));
  console.log('Mean NDSI Dec 2020: ' + (ndsi2020 !== null ? ndsi2020.toFixed(4) : 'null'));

  // Validate results
  if (ndsi2019 === null || ndsi2020 === null || isNaN(ndsi2019) || isNaN(ndsi2020)) {
    console.log('Calculation resulted in invalid values.');
    console.log('C3');
    return;
  }

  if (ndsi2019 < -1 || ndsi2019 > 1 || ndsi2020 < -1 || ndsi2020 > 1) {
    console.log('NDSI values outside valid range [-1, 1].');
    console.log('C3');
    return;
  }

  // Compare: Was 2020 lower than 2019?
  if (ndsi2020 < ndsi2019) {
    console.log('Yes, NDSI 2020 (' + ndsi2020.toFixed(4) + ') < NDSI 2019 (' + ndsi2019.toFixed(4) + ')');
    console.log('A');
  } else {
    console.log('No, NDSI 2020 (' + ndsi2020.toFixed(4) + ') >= NDSI 2019 (' + ndsi2019.toFixed(4) + ')');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
